class Solution {
  public String generateString(String str1, String str2) {
    int n = str1.length(), m = str2.length(), len = n + m - 1;
    char[] w = new char[len];
    boolean[] fixed = new boolean[len];
    for (int i = 0; i < n; i++) {
      if (str1.charAt(i) != 'T') continue;
      for (int j = 0; j < m; j++) {
        char c = str2.charAt(j);
        if (fixed[i + j] && w[i + j] != c) return "";
        w[i + j] = c;
        fixed[i + j] = true;
      }
    }
    for (int i = 0; i < len; i++) if (!fixed[i]) w[i] = 'a';
    for (int i = 0; i < n; i++) {
      if (str1.charAt(i) != 'F') continue;
      boolean equal = true;
      for (int j = 0; j < m && equal; j++) if (w[i + j] != str2.charAt(j)) equal = false;
      if (!equal) continue;
      int p = -1;
      for (int j = m - 1; j >= 0; j--) {
        if (!fixed[i + j]) {
          p = i + j;
          break;
        }
      }
      if (p < 0) return "";
      w[p] = 'b';
      fixed[p] = true;
    }
    return new String(w);
  }
}
